package com.bank.topearner.service;

import com.bank.topearner.model.Employee;
import java.util.Comparator;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class TopEarnerService {
    private static final Logger log = Logger.getLogger(TopEarnerService.class.getName());

    public List<Employee> bySalaryDescending(List<Employee> employees) {
        log.info(() -> "Sorting " + employees.size() + " employees by salary descending");
        return employees.stream()
                // Ascending comparator, then reversed() → highest first.
                .sorted(Comparator.comparing(Employee::getSalary).reversed())
                .collect(Collectors.toList());
    }
}
