    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", new BigDecimal("95000")),
            new Employee("Priya",  new BigDecimal("72000")),
            new Employee("Amit",   new BigDecimal("48000")),
            new Employee("Neha",   new BigDecimal("60000"))
        );

        new TopEarnerService().bySalaryDescending(staff)
            .forEach(e -> log.info(() -> "Descending: " + e));
    }
}
